final case class Reservation(seats: Int, taken: Int)
sealed trait Booking
object Booking {
  final case class Ok(ref: String) extends Booking
  final case class Rejected(reason: String) extends Booking
}
def reserve(r: Reservation, requested: Int, ref: String): Either[String, Booking.Ok] =
  if (requested <= 0) Left("invalid seat count")
  else if (r.taken + requested > r.seats) Left("no capacity")
  else Right(Booking.Ok(ref))

